// Standardized 6-level adventure questions: 960 questions across 8 categories (20 q / level)
import type { QuestionData } from "../components/quiz-models/types";

// ============================================
// STANDARDIZED LEVEL DEFINITIONS
// ============================================
export const ADVENTURE_LEVEL_DEFINITIONS = [
  { level: 1, name: "Pemula", color: "#EA580C", bgColor: "#FFEDD5", borderColor: "#C2410C" },
  { level: 2, name: "Dasar",   color: "#059669", bgColor: "#D1FAE5", borderColor: "#047857" },
  { level: 3, name: "Menengah", color: "#0284C7", bgColor: "#E0F2FE", borderColor: "#0369A1" },
  { level: 4, name: "Lanjutan", color: "#7C3AED", bgColor: "#EDE9FE", borderColor: "#6D28D9" },
  { level: 5, name: "Mahir",   color: "#D97706", bgColor: "#FEF08A", borderColor: "#B45309" },
  { level: 6, name: "Juara",   color: "#DC2626", bgColor: "#FEE2E2", borderColor: "#991B1B" },
];

export interface QuizAdventureLevel {
  level: number;
  name?: string;
  color?: string;
  bgColor?: string;
  borderColor?: string;
  questions: QuestionData[];
}

// ============================================
// LOCAL STORAGE UTILITIES
// ============================================
export const QUIZ_PROGRESS_STORAGE_KEY = "tartila_quiz_level_progress";

export function getCategoryUnlockedLevel(category: string): number {
  if (typeof window === "undefined") return 1;
  try {
    const raw = localStorage.getItem(QUIZ_PROGRESS_STORAGE_KEY);
    if (!raw) return 1;
    const parsed = JSON.parse(raw);
    const lvl = Number(parsed[category]) || 1;
    return Math.max(1, Math.min(6, lvl));
  } catch {
    return 1;
  }
}

export function saveCategoryLevelCompleted(
  category: string,
  completedLevel: number,
): void {
  if (typeof window === "undefined") return;
  try {
    const raw = localStorage.getItem(QUIZ_PROGRESS_STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : {};
    const currentMax = Number(parsed[category]) || 1;
    if (completedLevel >= currentMax && completedLevel < 6) {
      parsed[category] = completedLevel + 1;
      localStorage.setItem(QUIZ_PROGRESS_STORAGE_KEY, JSON.stringify(parsed));
    }
  } catch {
    // ignore
  }
}

export function buildLevels(questions: QuestionData[]): QuizAdventureLevel[] {
  const chunkSize = Math.max(1, Math.floor(questions.length / 6));
  return ADVENTURE_LEVEL_DEFINITIONS.map((def, idx) => ({
    level: def.level,
    name: def.name,
    color: def.color,
    bgColor: def.bgColor,
    borderColor: def.borderColor,
    questions: questions.slice(
      idx * chunkSize,
      idx === 5 ? questions.length : (idx + 1) * chunkSize,
    ),
  }));
}

